CREATE TABLE IF NOT EXISTS app_user (id VARCHAR(100) PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS project (id VARCHAR(36) PRIMARY KEY, title VARCHAR(160) NOT NULL);
CREATE TABLE IF NOT EXISTS member (project_id VARCHAR(36) NOT NULL REFERENCES project(id), user_id VARCHAR(100) NOT NULL REFERENCES app_user(id), role VARCHAR(10) NOT NULL, PRIMARY KEY(project_id,user_id));
CREATE TABLE IF NOT EXISTS material (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES project(id), filename VARCHAR(180) NOT NULL, body TEXT NOT NULL, digest VARCHAR(64) NOT NULL, creator VARCHAR(100) NOT NULL, created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS profile (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES project(id), title VARCHAR(160) NOT NULL, published_id VARCHAR(36));
CREATE TABLE IF NOT EXISTS profile_version (id VARCHAR(36) PRIMARY KEY, profile_id VARCHAR(36) NOT NULL REFERENCES profile(id), base_id VARCHAR(36), status VARCHAR(12) NOT NULL, content TEXT NOT NULL, work TEXT NOT NULL, creator VARCHAR(100) NOT NULL, reviewer VARCHAR(100), review_note VARCHAR(1000), created_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS job (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES project(id), profile_id VARCHAR(36) NOT NULL REFERENCES profile(id), kind VARCHAR(10) NOT NULL, status VARCHAR(12) NOT NULL, payload TEXT NOT NULL, result TEXT, error_code VARCHAR(40), attempt INT NOT NULL DEFAULT 0, lease_token VARCHAR(36), lease_until BIGINT, creator VARCHAR(100) NOT NULL, created_at BIGINT NOT NULL);
CREATE INDEX IF NOT EXISTS job_claim_idx ON job(status,created_at);
CREATE TABLE IF NOT EXISTS audit (id VARCHAR(36) PRIMARY KEY, project_id VARCHAR(36) NOT NULL REFERENCES project(id), actor VARCHAR(100) NOT NULL, action VARCHAR(40) NOT NULL, resource VARCHAR(36) NOT NULL, created_at BIGINT NOT NULL);

CREATE TABLE IF NOT EXISTS profile_archive (profile_id VARCHAR(36) PRIMARY KEY REFERENCES profile(id), deleted_at BIGINT NOT NULL);
CREATE TABLE IF NOT EXISTS job_progress (job_id VARCHAR(36) PRIMARY KEY REFERENCES job(id), completed INT NOT NULL DEFAULT 0, total INT NOT NULL);

CREATE TABLE IF NOT EXISTS job_archive (job_id VARCHAR(36) PRIMARY KEY REFERENCES job(id), deleted_by VARCHAR(100) NOT NULL, deleted_at BIGINT NOT NULL);
